    auto audio=render(p,assets,root,96000,127),blocks=render(p,assets,root,96000,511);bool same=true;for(int c=0;c<2;++c)for(int n=0;n<96000;++n)same&=audio.getSample(c,n)==blocks.getSample(c,n)&&std::isfinite(audio.getSample(c,n));expect(same&&audio.getRMSLevel(0,0,96000)>.0001f,"synth/effect/Master automation is audible, finite and callback-size independent");auto dry=p;dry.clips.resize(1);auto constant=render(dry,assets,root,96000,127);double difference=0;for(int n=0;n<96000;++n)difference+=std::abs(constant.getSample(0,n)-audio.getSample(0,n));expect(difference>1,"extended automation changes actual rendered audio without rewriting static settings");
    RenderSettings format;format.bits=32;format.endBeat=4;format.tailSeconds=0;auto wav=root.getChildFile("parameter-automation.wav");expect(renderAudio(p,assets,root,wav,format).wasOk(),"automated synth/effect parameters export to float WAV");String error;auto sample=assets.load(wav,error);same=sample&&sample->audio.getNumSamples()==96000;if(same)for(int c=0;c<2;++c)for(int n=0;n<96000;++n)same&=std::abs(sample->audio.getSample(c,n)-audio.getSample(c,n))<1e-6f;expect(same,"offline and callback automation use identical parameter/control timing");
    auto engine=makeEngine(p,assets,root);AudioBuffer<float> scratch(2,512);engine->seekRequested.store(.75);engine->render(scratch.getWritePointer(0),scratch.getWritePointer(1),512);float synth=engine->automationReadout[7][59].load(),master=engine->automationReadout[maxTracks][17].load();expect(synth>.6f&&synth<.7f&&master>.5f&&master<.6f,"seek chases synth and Master effect automation readouts");engine->seekRequested.store(3);engine->render(scratch.getWritePointer(0),scratch.getWritePointer(1),512);expect(engine->automationReadout[7][59].load()==-1&&engine->automationReadout[maxTracks][17].load()==-1,"clip ends restore static controls and clear live readout");engine->stop();engine->render(scratch.getWritePointer(0),scratch.getWritePointer(1),512);expect(engine->automationReadout[7][10].load()==-1&&p.tracks[7].synth.cutoff==12000,"stop clears automation without committing transient values into the song");
    auto looped=p;looped.loop=true;auto loopEngine=makeEngine(looped,assets,root);loopEngine->seekRequested.store(looped.songLength()-.01);loopEngine->render(scratch.getWritePointer(0),scratch.getWritePointer(1),512);expect(loopEngine->completedLoops.load()>=1&&loopEngine->position.load()<.1&&loopEngine->automationReadout[7][59].load()>.93f&&loopEngine->automationReadout[maxTracks][17].load()>.68f,"loop wrap chases new synth and Master curves at their opening values");
    auto primedRender=[&](int prime){auto e=makeEngine(p,assets,root);e->playing.store(false);AudioBuffer<float> warm(2,512),result(2,4096);for(int n=0;n<prime;n+=512)e->render(warm.getWritePointer(0),warm.getWritePointer(1),jmin(512,prime-n));e->start();for(int n=0;n<4096;n+=512)e->render(result.getWritePointer(0,n),result.getWritePointer(1,n),512);return result;};auto primeA=primedRender(16384),primeB=primedRender(16385);same=true;for(int c=0;c<2;++c)for(int n=0;n<4096;++n)same&=primeA.getSample(c,n)==primeB.getSample(c,n);expect(same,"stopped callbacks cannot shift the transport-relative effect automation control grid");
