    FiniteEcho echo;echo.prepare(48000);EchoSettings e{true,2,20,.2f,1};echo.setSettings(e);for(int n=0;n<4800;++n){float l=.1f,r=-.1f;echo.process(l,r);}bool continuous=true;for(int n=0;n<4000;++n){e.interval=20+n*.005f;echo.setSettings(e,true);float l=.1f,r=-.1f;echo.process(l,r);continuous&=std::isfinite(l)&&l>.05f&&r<-.05f;}expect(continuous,"automated delay intervals preserve echo history through continuous smoothed sweeps");
